/**
 * THINK readability (plan section 5): a blind pairwise judge compares the Direct Python with the
 * Python compiled from the same model's Canon program for the same seed and run, where both pass
 * every hidden test. Up to 100 pairs, drawn at random with a fixed seed. The generated files'
 * "Generated by Canon ... Do not edit" headers and hash lines are removed so the judge cannot see
 * the label; the order (A/B) is randomized. To avoid self-preference, Claude Opus 5.5 judges the
 * pairs written by GPT-6.2 Sol and by Qwen, and GPT-6.2 Sol judges the pairs written by Claude.
 * Writes results/judge.jsonl.   npx tsx --conditions=source analysis/judge.ts
 */
import { appendFileSync, existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { checkProject, generateFastapi } from "@canon/compiler";
import { mulberry32 } from "../lib/gen.js";
import { BENCH } from "../lib/seed.js";
import { makeModel } from "../runner/models.js";

const JUDGE_PROMPT = (a: string, b: string) =>
  `Two Python implementations of the same functions follow. Both are correct: they pass the same tests. ` +
  `Imagine you own this code and must maintain and extend it for the next year.\n\n` +
  `Implementation A:\n\`\`\`python\n${a.trim()}\n\`\`\`\n\nImplementation B:\n\`\`\`python\n${b.trim()}\n\`\`\`\n\n` +
  `Which would you rather maintain? Give at most three sentences of reasons, then end with a last line of exactly "ANSWER: A" or "ANSWER: B".`;

function compiledPython(canon: string): string {
  const p = checkProject([{ name: "main", path: "canon/main.cn", src: canon }]);
  const files = generateFastapi(p);
  const pick = (n: string) => files.find((f) => f.path === n)?.text ?? "";
  const strip = (t: string) => t.split("\n").filter((l) => !/^# (Generated by Canon|canon-hash:)/.test(l)).join("\n").trim();
  const models = strip(pick("models.py"));
  const logic = strip(pick("logic.py"));
  return (/class \w+\(BaseModel\)/.test(models) ? `# models.py\n${models}\n\n# logic.py\n` : "") + logic;
}

const out = join(BENCH, "results", "judge.jsonl");
const done = new Set(existsSync(out) ? readFileSync(out, "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l).key) : []);
const pairs: { model: string; seed: string; run: number; direct: string; canon: string }[] = [];
for (const model of ["opus", "gpt", "qwen7b"]) {
  const f = join(BENCH, "results", `think-${model}.jsonl`);
  if (!existsSync(f)) continue;
  const recs = readFileSync(f, "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l));
  for (const r of recs.filter((x) => x.arm === "canon->py" && x.thinkPass)) {
    const d = recs.find((x) => x.arm === "py" && x.seed === r.seed && x.run === r.run && x.thinkPass);
    const w = join(BENCH, "results", `write-${model}.jsonl`);
    if (!d) continue;
    const direct = readFileSync(w, "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l)).find((x) => x.key === d.key.replace("|think|", "|write|"))?.final;
    if (direct) pairs.push({ model, seed: r.seed, run: r.run, direct, canon: r.final });
  }
}
const rnd = mulberry32(99);
pairs.sort(() => rnd() - 0.5);
const chosen = pairs.slice(0, 100);
const judges = { opus: makeModel("gpt"), gpt: makeModel("opus"), qwen7b: makeModel("opus") } as const;
let n = 0;
await Promise.all(
  Array.from({ length: 6 }, async () => {
    while (n < chosen.length) {
      const p = chosen[n++];
      const key = `${p.model}|${p.seed}|${p.run}`;
      if (done.has(key)) continue;
      const compiled = compiledPython(p.canon);
      const canonIsA = rnd() < 0.5;
      const [a, b] = canonIsA ? [compiled, p.direct] : [p.direct, compiled];
      const judge = judges[p.model as keyof typeof judges];
      try {
        const reply = await judge.chat("You are a senior Python engineer reviewing code.", [{ role: "user", content: JUDGE_PROMPT(a, b) }]);
        const m = /ANSWER:\s*([AB])/i.exec(reply.text);
        const pick = m ? m[1].toUpperCase() : null;
        const prefersCompiled = pick === null ? null : (pick === "A") === canonIsA;
        appendFileSync(out, JSON.stringify({ key, model: p.model, judge: judge.id, seed: p.seed, run: p.run, canonIsA, pick, prefersCompiled, reason: reply.text.slice(-800), usage: reply.usage }) + "\n");
        console.log(`${key}: judge ${judge.id} picked ${pick} (${prefersCompiled ? "compiled" : "direct"})`);
      } catch (e) {
        console.log(`ERROR ${key}: ${(e as Error).message}`);
      }
    }
  }),
);
